static void *find_widget_suffix(void **begin, void **end, const char *target, int depth)
{
    if (!begin || !end || depth > 10) return NULL;
    /* sanity the enumerator range: a bad ABI/stale vector would give a wild
     * begin..end and iterating it would read wild memory forever. */
    if (end < begin || (size_t)(end - begin) > 2048) return NULL;
    for (void **it = begin; it != end; ++it) {
        if (--g_find_budget <= 0) return NULL;   /* total-node cap */
        if (!readable(it, 8)) return NULL;
        void *w = *it;
        if (!readable(w, 8)) continue;
        if (g_widget_getname) {
            const void *ns = g_widget_getname(w);
            char nm[128]; read_mstring(ns, nm, sizeof nm);
            const char *suf = strrchr(nm, '_'); suf = suf ? suf + 1 : nm;
            if (strcmp(suf, target) == 0) return w;
        }
        if (g_widget_getenum) {
            unsigned char ce[32];
            g_widget_getenum(w, ce);
            void *found = find_widget_suffix(*(void ***)(ce + 8), *(void ***)(ce + 16), target, depth + 1);
            if (found) return found;
        }
    }
    return NULL;
}

static void *settings_find(void *gui, const char *target)
{
    if (!g_gui_getenum) return NULL;
    g_find_budget = 4000;
    unsigned char ge[32];
    g_gui_getenum(gui, ge);
    return find_widget_suffix(*(void ***)(ge + 8), *(void ***)(ge + 16), target, 0);
}

static void *make_child(void *parent, const char *type, const char *skin,
                        int l, int t, int w, int h, const char *name)
{
    if (!g_widget_createwidget || !parent) return NULL;
    unsigned char ty[32], sk[32], nm[32];
    void *tf = make_mstr_long(ty, type);
    void *sf = make_mstr_long(sk, skin);
    void *nf = make_mstr_long(nm, name);
    void *child = g_widget_createwidget(parent, ty, sk, l, t, w, h, 0, nm);
    if (tf) free(tf);
    if (sf) free(sf);
    if (nf) free(nf);
    return child;
}

static int try_move_to_pos(void *pc, const Vec3 *tgt)
{
    if (g_movetopos_dead) return 0;
    void **vt = *(void ***)pc;
    if (!in_module(vt)) return 0;
    void (*fn)(void *, void *, void *, const Vec3 *) =
        (void (*)(void *, void *, void *, const Vec3 *))vt[CHAR_VT_PLAYERMOVE];
    if (!in_module((void *)fn)) return 0;
    __try {
        fn(pc, NULL, NULL, tgt);          /* NULL,NULL = plain ground point */
    } __except (STOBE_SEH_FILTER) {
        g_movetopos_dead = 1;
        logline("playerMoveOrderDefault FAULTED -- disabled for this session");
        return 0;
    }
    return 1;
}

/* STOBE voice-mode bridge.
 * STOBE itself only has one PTT binding (U in this setup), so KenshiFP adds
 * lightweight modifier modes by leaving one-shot marker files for StobeServer:
 *   U         -> normal spoken dialogue
 *   Shift+U   -> inject_chat (roleplay/world event)
 *   Ctrl+U    -> cheat/action instruction (prefer a real Kenshi action)
 *
 * Voice target lock:
 * Stobe already chooses/validates a target immediately on PTT key-down and stores
 * that target in Voice::Context.  Its stock send path validates range a SECOND
 * time after STT finishes, which can reject the exact same following squadmate if
 * they drifted a little while the player was speaking.  For the installed Stobe
 * build (sha256 d634cf40...), g_proximityRadius is at module RVA 0x247290.
 *
 * We leave the normal radius untouched during key-down, so the EARLY check is
 * authoritative.  Only after a real push-to-talk hold is released do we
 * temporarily relax the *second* distance check.  The target itself remains the
 * handle captured by Stobe at recording start; this does not choose a new NPC.
 * The patch automatically restores after 15 seconds and has strong value guards
 * so an unexpected Stobe build is left untouched. */
#define STOBE_VOICE_LOCK_RANGE 500.0f
#define STOBE_VOICE_LOCK_MIN_HOLD_MS 350u
#define STOBE_VOICE_LOCK_WINDOW_MS 15000u
static int g_stobe_range_lock;
static float g_stobe_saved_range;
static DWORD g_stobe_range_restore_at;
/* Was KenshiFP writing Stobe.dll's g_proximityRadius by fixed RVA; now direct. */
static int stobe_set_voice_range_lock(int enable)
{
    float *prox = StobeGoals_ProximityRadius();
    if (!prox) return 0;
    float p = *prox;
    if (!(p >= 1.0f && p <= 5000.0f)) return 0;
    if (enable) {
        if (!g_stobe_range_lock) {
            g_stobe_saved_range = p;
            *prox = p > STOBE_VOICE_LOCK_RANGE ? p : STOBE_VOICE_LOCK_RANGE;
            g_stobe_range_lock = 1;
            logline("[stobe] voice target locked: post-STT range %.1f -> %.1f", p, *prox);
        }
    } else if (g_stobe_range_lock) {
        *prox = g_stobe_saved_range;
        logline("[stobe] voice target lock released: range restored to %.1f", g_stobe_saved_range);
        g_stobe_range_lock = 0;
        g_stobe_saved_range = 0.0f;
        g_stobe_range_restore_at = 0;
    }
    return 1;
}
static int stobe_mod_path(char *out, size_t outsz, const char *leaf);
/* lifelike_interrupt.flag (server: danger) -> Stobe's own chat/TTS preemption.
 * lifelike_initiative.flag is consumed by Stobe's UpdateLifelikeInitiativeFlag (main.cpp).
 * KenshiFP used fixed Stobe.dll RVAs here and built the path as exe dir + RE_Kenshi\...,
 * which never existed, so this signal was never consumed before. A flag older than 30 s
 * is stale and dropped unused. */
static void stobe_lifelike_signal_tick(void)
{
    static DWORD next_poll;
    DWORD now = GetTickCount();
    if (next_poll && (LONG)(now - next_poll) < 0) return;
    next_poll = now + 100;
    char path[MAX_PATH * 2] = {0};
    if (!stobe_mod_path(path, sizeof(path), "lifelike_interrupt.flag")) return;
    WIN32_FILE_ATTRIBUTE_DATA fa;
    if (!GetFileAttributesExA(path, GetFileExInfoStandard, &fa)) return;
    FILETIME ft; GetSystemTimeAsFileTime(&ft);
    ULARGE_INTEGER t0, t1;
    t0.LowPart = fa.ftLastWriteTime.dwLowDateTime; t0.HighPart = fa.ftLastWriteTime.dwHighDateTime;
    t1.LowPart = ft.dwLowDateTime; t1.HighPart = ft.dwHighDateTime;
    double age_s = t1.QuadPart > t0.QuadPart ? (double)(t1.QuadPart - t0.QuadPart) / 1.0e7 : 0.0;
    DeleteFileA(path);
    if (age_s > 30.0) {
        logline("[stobe] lifelike interrupt flag stale (%.0f s) -- dropped", age_s);
        return;
    }
    long generation = StobeGoals_ChatInterrupt();
    logline("[stobe] lifelike danger preempted chat/TTS generation=%ld", generation);
}
