static int stobe_copy_native_string(const void *str_obj, char *out, size_t outsz)
{
    if (!out || outsz < 2) return 0;
    out[0] = '\0';
    if (!readable(str_obj, 0x20)) return 0;
    size_t len = *(const size_t *)((uintptr_t)str_obj + 0x10);
    size_t cap = *(const size_t *)((uintptr_t)str_obj + 0x18);
    if (len == 0 || len > 4096 || cap < len) return 0;
    const char *src = (const char *)str_obj;
    if (cap > 15) {
        src = *(const char * const *)str_obj;
        if (!readable(src, len)) return 0;
    }
    if (len >= outsz) len = outsz - 1;
    memcpy(out, src, len);
    out[len] = '\0';
    return 1;
}

static void stobe_ascii_lower(char *s)
{
    for (; s && *s; ++s)
        if (*s >= 'A' && *s <= 'Z') *s = (char)(*s - 'A' + 'a');
}

static int stobe_query_slot_mask(const char *query)
{
    char q[192] = {0};
    strncpy(q, query ? query : "", sizeof(q) - 1);
    stobe_ascii_lower(q);
    int mask = 0;
    if (strstr(q, "weapon") || strstr(q, "sword") || strstr(q, "blade") ||
        strstr(q, "katana") || strstr(q, "sabre") || strstr(q, "saber") ||
        strstr(q, "club") || strstr(q, "axe") || strstr(q, "polearm") ||
        strstr(q, "crossbow"))
        mask |= (1 << ATTACH_WEAPON) | (1 << ATTACH_BACK);
    if (strstr(q, "hat") || strstr(q, "helmet") || strstr(q, "headwear") ||
        strstr(q, "bandana") || strstr(q, "hood") || strstr(q, "cap"))
        mask |= 1 << ATTACH_HAT;
    if (strstr(q, "facewear") || strstr(q, "mask") || strstr(q, "goggle") ||
        strstr(q, "glass") || strstr(q, "eyewear"))
        mask |= 1 << ATTACH_EYES;
    if (strstr(q, "shirt") || strstr(q, "undershirt"))
        mask |= 1 << ATTACH_SHIRT;
    if (strstr(q, "armor") || strstr(q, "armour") || strstr(q, "chest") ||
        strstr(q, "body") || strstr(q, "vest") || strstr(q, "jacket"))
        mask |= 1 << ATTACH_BODY;
    if (strstr(q, "pants") || strstr(q, "trouser") || strstr(q, "legwear"))
        mask |= 1 << ATTACH_LEGS;
    if (strstr(q, "boot") || strstr(q, "shoe") || strstr(q, "sandal"))
        mask |= 1 << ATTACH_BOOTS;
    if (strstr(q, "glove") || strstr(q, "gauntlet"))
        mask |= 1 << ATTACH_GLOVES;
    if (strstr(q, "neck") || strstr(q, "scarf"))
        mask |= 1 << ATTACH_NECK;
    if (strstr(q, "backpack") || strstr(q, "back pack"))
        mask |= 1 << ATTACH_BACKPACK;
    if (strstr(q, "belt"))
        mask |= 1 << ATTACH_BELT;
    return mask;
}

static int stobe_ci_contains(const char *haystack, const char *needle)
{
    char h[256] = {0}, n[192] = {0};
    if (!haystack || !needle || !*needle) return 0;
    strncpy(h, haystack, sizeof(h) - 1);
    strncpy(n, needle, sizeof(n) - 1);
    stobe_ascii_lower(h);
    stobe_ascii_lower(n);
    return strstr(h, n) != NULL;
}

static void *stobe_find_character_by_serial(void *gw, uint32_t serial)
{
    if (!gw || !serial) return NULL;
    /* Bug 118: squad members can be far from the first squad member (working a
     * goal at the mine); look them up in the squad list before the sphere. */
    if (readable((void *)((uintptr_t)gw + GW_PLAYER), 8)) {
        void *player = *(void **)((uintptr_t)gw + GW_PLAYER);
        if (readable((void *)((uintptr_t)player + PI_PLAYERCHARS + LEK_STUFF), 8)) {
            uint32_t count = *(uint32_t *)((uintptr_t)player + PI_PLAYERCHARS + LEK_COUNT);
            void **stuff = *(void ***)((uintptr_t)player + PI_PLAYERCHARS + LEK_STUFF);
            if (stuff && count <= 4096 && readable(stuff, count * sizeof(void *))) {
                for (uint32_t i = 0; i < count; i++) {
                    void *c = stuff[i];
                    if (!char_valid(c) || !readable((void *)((uintptr_t)c + CHAR_HANDLE + HAND_IDS), 20))
                        continue;
                    if (((uint32_t *)((uintptr_t)c + CHAR_HANDLE + HAND_IDS))[4] == serial)
                        return c;
                }
            }
        }
    }
    if (!g_stobe_getchars) {
        HMODULE klib = GetModuleHandleA("KenshiLib.dll");
        if (klib)
            g_stobe_getchars = (stobe_getchars_t)GetProcAddress(klib, KLIB_GETCHARS_SYM);
        if (!g_stobe_getchars) return NULL;
    }

    void *pc = first_player_char(gw);
    Vec3 center = {0,0,0};
    if (!pc || !char_position(pc, &center)) return NULL;

    void *nearby[512] = {0};
    StobePtrLektor out;
    memset(&out, 0, sizeof(out));
    out.max_size = 512;
    out.stuff = nearby;
    g_stobe_getchars(gw, &out, &center, 750.0f, 750.0f, 750.0f, 256, 256, NULL);

    if (out.count > 512 || !out.stuff) return NULL;
    for (uint32_t i = 0; i < out.count; ++i) {
        void *c = out.stuff[i];
        if (!char_valid(c) || !readable((void *)((uintptr_t)c + CHAR_HANDLE + HAND_IDS), 20))
            continue;
        uint32_t *ids = (uint32_t *)((uintptr_t)c + CHAR_HANDLE + HAND_IDS);
        if (ids[4] == serial)
            return c;
    }
    return NULL;
}

/* Resolve a real inventory Item's GameData. The KenshiLib header puts
 * RootObjectBase::data at 0x40; ITEM_GAMEDATA (0x78) is only proven for the
 * appearance-map render entities. An offset is accepted only when its GameData
 * name agrees with the Item's displayName, so a wrong offset can never hand an
 * arbitrary pointer to Kenshi's inventory functions. */
static void *stobe_real_item_gamedata(void *item, char *name, size_t namesz, int *which_off)
{
    static const size_t offs[2] = { ITEM_ROOT_DATA, ITEM_GAMEDATA };
    char disp[160] = {0};
    if (name && namesz) name[0] = '\0';
    if (which_off) *which_off = 0;
    if (!item || !stobe_copy_native_string((void *)((uintptr_t)item + ROOT_DISPLAY_NAME),
                                           disp, sizeof(disp)))
        return NULL;
    for (int i = 0; i < 2; ++i) {
        if (!readable((void *)((uintptr_t)item + offs[i]), sizeof(void *))) continue;
        void *gd = *(void **)((uintptr_t)item + offs[i]);
        char n[160] = {0};
        if (!gd || !stobe_copy_native_string((void *)((uintptr_t)gd + GD_NAME), n, sizeof(n)))
            continue;
        if (!stobe_ci_contains(n, disp) && !stobe_ci_contains(disp, n))
            continue;
        if (name && namesz) {
            strncpy(name, n, namesz - 1);
            name[namesz - 1] = '\0';
        }
        if (which_off) *which_off = (int)offs[i];
        return gd;
    }
    return NULL;
}

/* GameData of a REAL inventory Item (from Inventory::_allItems or a section).
 * Prefer the name-verified lookup; fall back to RootObjectBase::data (+0x40,
 * KenshiLib header, confirmed in game 2026-09-28) when the display name differs
 * from the base name (renamed/unique items). Never ITEM_GAMEDATA (+0x78): that
 * offset belongs to appearance-map render entities, not Items. */
static void *stobe_item_gamedata(void *item)
{
    void *gd = stobe_real_item_gamedata(item, NULL, 0, NULL);
    if (gd) return gd;
    if (!item || !readable((void *)((uintptr_t)item + ITEM_ROOT_DATA), sizeof(void *))) return NULL;
    gd = *(void **)((uintptr_t)item + ITEM_ROOT_DATA);
    char name[8] = {0};
    return (gd && stobe_copy_native_string((void *)((uintptr_t)gd + GD_NAME), name, sizeof(name))) ? gd : NULL;
}

static void *stobe_find_equipped_item(void *npc, const char *query, char *matched_name, size_t matched_sz)
{
    /* Search the NPC's REAL equipment inventory sections. The appearance
     * (render) map is not the inventory: its entries never passed the
     * isEquipped check ("no equipped match"), and a match there would have
     * handed a render object to the inventory move below. */
    if (matched_name && matched_sz) matched_name[0] = '\0';
    if (!npc || !query || !*query) return NULL;

    HMODULE klib = GetModuleHandleA("KenshiLib.dll");
    if (!klib) return NULL;
    if (!g_stobe_getinv)
        g_stobe_getinv = (stobe_getinv_t)GetProcAddress(klib, KLIB_GETINV_SYM);
    if (!g_stobe_inv_getallsections)
        g_stobe_inv_getallsections = (stobe_inv_getallsections_t)GetProcAddress(klib, KLIB_INV_GETALLSECTIONS_SYM);
    if (!g_stobe_invsect_hasitem)
        g_stobe_invsect_hasitem = (stobe_invsect_hasitem_t)GetProcAddress(klib, KLIB_INVSECT_HASITEM_SYM);
    if (!g_stobe_invsect_getitem)
        g_stobe_invsect_getitem = (stobe_invsect_getitem_t)GetProcAddress(klib, KLIB_INVSECT_GETITEM_SYM);
    if (!g_stobe_getinv || !g_stobe_inv_getallsections ||
        !g_stobe_invsect_hasitem || !g_stobe_invsect_getitem) {
        logline("[stobe] unequip lookup exports missing");
        return NULL;
    }

    void *inv = g_stobe_getinv(npc);
    if (!inv) {
        logline("[stobe] unequip lookup: no inventory");
        return NULL;
    }
    StobePtrLektor *sections = (StobePtrLektor *)g_stobe_inv_getallsections(inv);
    if (!sections || !readable(sections, sizeof(*sections)) ||
        sections->count == 0 || sections->count > 128 || !sections->stuff ||
        !readable(sections->stuff, (size_t)sections->count * sizeof(void *))) {
        logline("[stobe] unequip lookup: invalid section list inv=%p", inv);
        return NULL;
    }

    int wanted_slots = stobe_query_slot_mask(query);
    void *best = NULL;
    int best_score = 0;
    char best_name[160] = {0};
    int equip_sections = 0;
    for (uint32_t i = 0; i < sections->count; ++i) {
        void *section = sections->stuff[i];
        if (!section || !readable(section, 0xD1)) continue;
        if (!*(unsigned char *)((uintptr_t)section + 0xB4)) continue;   /* isAnEquippedItemSection */
        ++equip_sections;

        void *item = g_stobe_invsect_getitem(section);
        if (!item || !readable(item, ITEM_IS_EQUIPPED + 1)) continue;
        if (!g_stobe_invsect_hasitem(section, item)) continue;

        char sname[96] = {0};
        stobe_copy_native_string((void *)((uintptr_t)section + 0x08), sname, sizeof(sname));
        int equipped = *(unsigned char *)((uintptr_t)item + ITEM_IS_EQUIPPED) != 0;
        int slot = *(int *)((uintptr_t)item + ITEM_SLOT_TYPE);
        int limited = *(int *)((uintptr_t)section + 0xB8);             /* limitedSlot */
        char name[160] = {0};
        int gdoff = 0;
        void *gd = stobe_real_item_gamedata(item, name, sizeof(name), &gdoff);
        int qty = readable((void *)((uintptr_t)item + 0x12C), sizeof(int))
            ? *(int *)((uintptr_t)item + 0x12C) : -1;                     /* Item::quantity */
        logline("[stobe] unequip candidate item=%p section=%s slot=%d limited=%d equipped=%d qty=%d name=%s gdOff=0x%x",
                item, sname[0] ? sname : "(unnamed)", slot, limited, equipped, qty,
                name[0] ? name : "(unverified)", gdoff);
        if (!equipped || !gd) continue;

        int score = 0;
        if (stobe_ci_contains(name, query) || stobe_ci_contains(query, name))
            score = 1000;
        else if ((slot >= 0 && slot < 31 && (wanted_slots & (1 << slot))) ||
                 (limited >= 0 && limited < 31 && (wanted_slots & (1 << limited))))
            score = 100;
        if (score > best_score) {
            best = item;
            best_score = score;
            strncpy(best_name, name, sizeof(best_name) - 1);
        }
    }
    if (!best)
        logline("[stobe] unequip lookup: sections=%u equipSections=%d query=%s",
                sections->count, equip_sections, query);
    if (best && matched_name && matched_sz) {
        strncpy(matched_name, best_name, matched_sz - 1);
        matched_name[matched_sz - 1] = '\0';
    }
    return best;
}

static int stobe_unequip_item(void *npc, void *item)
{
    /* Section-aware real unequip.
     *
     * Never call Character::unequipItem / CharacterHuman::unequipItem directly.
     * Locate the actual InventorySection that owns the equipped Item, remove it
     * through that section so Kenshi receives the correct equipment callback
     * context, then place the SAME Item into a normal carried-inventory section.
     */
    if (!npc || !item || !readable(npc, 8) ||
        !readable(item, ITEM_IS_EQUIPPED + 1) ||
        !readable((void *)((uintptr_t)item + 0x12C), sizeof(int)))
        return 0;

    if (!*(unsigned char *)((uintptr_t)item + ITEM_IS_EQUIPPED))
        return 1;

    int qty = *(int *)((uintptr_t)item + 0x12C);
    if (qty < 1 || qty > 1000) {
        logline("[stobe] UNEQUIP_ITEM refused invalid native quantity qty=%d item=%p", qty, item);
        return 0;
    }

    HMODULE klib = GetModuleHandleA("KenshiLib.dll");
    if (!klib) return 0;

    if (!g_stobe_getinv)
        g_stobe_getinv = (stobe_getinv_t)GetProcAddress(klib, KLIB_GETINV_SYM);
    if (!g_stobe_inv_getallsections)
        g_stobe_inv_getallsections = (stobe_inv_getallsections_t)GetProcAddress(klib, KLIB_INV_GETALLSECTIONS_SYM);
    if (!g_stobe_invsect_hasitem)
        g_stobe_invsect_hasitem = (stobe_invsect_hasitem_t)GetProcAddress(klib, KLIB_INVSECT_HASITEM_SYM);
    if (!g_stobe_invsect_removeitem)
        g_stobe_invsect_removeitem = (stobe_invsect_removeitem_t)GetProcAddress(klib, KLIB_INVSECT_REMOVEITEM_SYM);
    if (!g_stobe_invsect_hasroom)
        g_stobe_invsect_hasroom = (stobe_invsect_hasroom_t)GetProcAddress(klib, KLIB_INVSECT_HASROOM_SYM);
    if (!g_stobe_invsect_additem)
        g_stobe_invsect_additem = (stobe_invsect_additem_t)GetProcAddress(klib, KLIB_INVSECT_ADDITEM_SYM);

    if (!g_stobe_getinv || !g_stobe_inv_getallsections ||
        !g_stobe_invsect_hasitem || !g_stobe_invsect_removeitem ||
        !g_stobe_invsect_hasroom || !g_stobe_invsect_additem)
        return 0;

    void *inv = g_stobe_getinv(npc);
    void *gd = stobe_real_item_gamedata(item, NULL, 0, NULL);
    if (!inv || !gd) {
        logline("[stobe] UNEQUIP_ITEM refused: item GameData not verified item=%p", item);
        return 0;
    }

    StobePtrLektor *sections = (StobePtrLektor *)g_stobe_inv_getallsections(inv);
    if (!sections || !readable(sections, sizeof(*sections)) ||
        sections->count == 0 || sections->count > 128 ||
        !sections->stuff ||
        !readable(sections->stuff, (size_t)sections->count * sizeof(void *))) {
        logline("[stobe] UNEQUIP_ITEM invalid inventory section list inv=%p", inv);
        return 0;
    }

    void *source = NULL;
    void *destination = NULL;
    char source_name[96] = {0};
    char destination_name[96] = {0};

    /* First find the section that truly owns this exact Item pointer. */
    for (uint32_t i = 0; i < sections->count; ++i) {
        void *section = sections->stuff[i];
        if (!section || !readable(section, 0xD1))
            continue;
        if (!g_stobe_invsect_hasitem(section, item))
            continue;

        source = section;
        stobe_copy_native_string((void *)((uintptr_t)section + 0x08),
                                 source_name, sizeof(source_name));
        break;
    }

    if (!source) {
        logline("[stobe] UNEQUIP_ITEM source section not found item=%p qty=%d", item, qty);
        return 0;
    }

    int source_is_equipped = *(unsigned char *)((uintptr_t)source + 0xB4) != 0;
    if (!source_is_equipped) {
        logline("[stobe] UNEQUIP_ITEM source is not equipment section item=%p section=%s",
                item, source_name[0] ? source_name : "(unknown)");
        return 0;
    }

    /* Select a real carried-inventory section, not another equipment/container
     * slot. Prefer the first enabled normal section that can accept the whole
     * native Item quantity. */
    for (uint32_t i = 0; i < sections->count; ++i) {
        void *section = sections->stuff[i];
        if (!section || section == source || !readable(section, 0xD1))
            continue;

        int is_equipped_section = *(unsigned char *)((uintptr_t)section + 0xB4) != 0;
        int is_container_slot = *(unsigned char *)((uintptr_t)section + 0xBC) != 0;
        int enabled = *(unsigned char *)((uintptr_t)section + 0xD0) != 0;
        if (is_equipped_section || is_container_slot || !enabled)
            continue;
        if (!g_stobe_invsect_hasroom(section, gd, qty))
            continue;

        destination = section;
        stobe_copy_native_string((void *)((uintptr_t)section + 0x08),
                                 destination_name, sizeof(destination_name));
        break;
    }

    if (!destination) {
        /* Full pack: drop it at the character's feet rather than refuse. It only
         * counts if the item really left the equipment section. */
        if (!g_stobe_inv_dropitem) {
            HMODULE klib = GetModuleHandleA("KenshiLib.dll");
            if (klib)
                g_stobe_inv_dropitem = (stobe_inv_dropitem_t)GetProcAddress(klib, KLIB_INV_DROPITEM_SYM);
        }
        if (g_stobe_inv_dropitem) {
            g_stobe_inv_dropitem(inv, item);
            int still_equipped = g_stobe_invsect_hasitem(source, item) ? 1 : 0;
            logline("[stobe] UNEQUIP_ITEM no carried section has room; dropped at feet item=%p qty=%d source=%s result=%s",
                    item, qty, source_name[0] ? source_name : "(unknown)",
                    still_equipped ? "failed" : "dropped");
            return still_equipped ? 0 : 1;
        }
        logline("[stobe] UNEQUIP_ITEM no carried section has room item=%p qty=%d source=%s",
                item, qty, source_name[0] ? source_name : "(unknown)");
        return 0;
    }

    logline("[stobe] UNEQUIP_ITEM section move begin item=%p qty=%d source=%s dest=%s",
            item, qty,
            source_name[0] ? source_name : "(unknown)",
            destination_name[0] ? destination_name : "(unknown)");

    /* This is the critical operation: remove from the actual equipment section,
     * allowing Kenshi's section callback machinery to perform the unequip with
     * correct section context. */
    if (!g_stobe_invsect_removeitem(source, item)) {
        logline("[stobe] UNEQUIP_ITEM source section remove failed item=%p source=%s",
                item, source_name[0] ? source_name : "(unknown)");
        return 0;
    }

    if (!g_stobe_invsect_additem(destination, item, qty)) {
        /* Best-effort rollback to the exact original equipment section. */
        int restored = g_stobe_invsect_additem(source, item, qty);
        logline("[stobe] UNEQUIP_ITEM destination add failed item=%p dest=%s rollback=%s",
                item,
                destination_name[0] ? destination_name : "(unknown)",
                restored ? "ok" : "FAILED");
        return 0;
    }

    if (!readable(item, ITEM_IS_EQUIPPED + 1))
        return 0;

    int still_equipped = *(unsigned char *)((uintptr_t)item + ITEM_IS_EQUIPPED) != 0;
    int source_still_has = g_stobe_invsect_hasitem(source, item);
    int destination_has = g_stobe_invsect_hasitem(destination, item);

    logline("[stobe] UNEQUIP_ITEM section move result item=%p qty=%d source=%s dest=%s sourceHas=%d destHas=%d equippedAfter=%d",
            item, qty,
            source_name[0] ? source_name : "(unknown)",
            destination_name[0] ? destination_name : "(unknown)",
            source_still_has, destination_has, still_equipped);

    if (still_equipped || source_still_has || !destination_has) {
        /* State is not what we promised. Attempt to restore the original slot
         * rather than leaving the item in an ambiguous state. */
        if (destination_has)
            (void)g_stobe_invsect_removeitem(destination, item);
        int restored = g_stobe_invsect_additem(source, item, qty);
        logline("[stobe] UNEQUIP_ITEM verification failed; rollback=%s item=%p",
                restored ? "ok" : "FAILED", item);
        return 0;
    }

    if (g_stobe_rethink)
        g_stobe_rethink(npc);
    return 1;
}

static int stobe_equip_item(void *npc, void *item)
{
    /* Section-aware real equip: the mirror of stobe_unequip_item. Move the
     * SAME Item from a carried section into the empty equipment section whose
     * limitedSlot matches the item's slot, so Kenshi's section callbacks run
     * the equip. Never calls Character-level (un)equip functions. */
    if (!npc || !item || !readable(item, ITEM_IS_EQUIPPED + 1) ||
        !readable((void *)((uintptr_t)item + 0x12C), sizeof(int)))
        return 0;
    if (*(unsigned char *)((uintptr_t)item + ITEM_IS_EQUIPPED))
        return 1;

    int qty = *(int *)((uintptr_t)item + 0x12C);
    int slot = *(int *)((uintptr_t)item + ITEM_SLOT_TYPE);
    if (qty < 1 || qty > 1000) {
        logline("[stobe] EQUIP_ITEM refused invalid native quantity qty=%d item=%p", qty, item);
        return 0;
    }

    HMODULE klib = GetModuleHandleA("KenshiLib.dll");
    if (!klib) return 0;
    if (!g_stobe_getinv)
        g_stobe_getinv = (stobe_getinv_t)GetProcAddress(klib, KLIB_GETINV_SYM);
    if (!g_stobe_inv_getallsections)
        g_stobe_inv_getallsections = (stobe_inv_getallsections_t)GetProcAddress(klib, KLIB_INV_GETALLSECTIONS_SYM);
    if (!g_stobe_invsect_hasitem)
        g_stobe_invsect_hasitem = (stobe_invsect_hasitem_t)GetProcAddress(klib, KLIB_INVSECT_HASITEM_SYM);
    if (!g_stobe_invsect_removeitem)
        g_stobe_invsect_removeitem = (stobe_invsect_removeitem_t)GetProcAddress(klib, KLIB_INVSECT_REMOVEITEM_SYM);
    if (!g_stobe_invsect_hasroom)
        g_stobe_invsect_hasroom = (stobe_invsect_hasroom_t)GetProcAddress(klib, KLIB_INVSECT_HASROOM_SYM);
    if (!g_stobe_invsect_additem)
        g_stobe_invsect_additem = (stobe_invsect_additem_t)GetProcAddress(klib, KLIB_INVSECT_ADDITEM_SYM);
    if (!g_stobe_invsect_getitem)
        g_stobe_invsect_getitem = (stobe_invsect_getitem_t)GetProcAddress(klib, KLIB_INVSECT_GETITEM_SYM);
    if (!g_stobe_getinv || !g_stobe_inv_getallsections || !g_stobe_invsect_hasitem ||
        !g_stobe_invsect_removeitem || !g_stobe_invsect_hasroom ||
        !g_stobe_invsect_additem || !g_stobe_invsect_getitem)
        return 0;

    void *inv = g_stobe_getinv(npc);
    void *gd = stobe_real_item_gamedata(item, NULL, 0, NULL);
    if (!inv || !gd) {
        logline("[stobe] EQUIP_ITEM refused: item GameData not verified item=%p", item);
        return 0;
    }
    StobePtrLektor *sections = (StobePtrLektor *)g_stobe_inv_getallsections(inv);
    if (!sections || !readable(sections, sizeof(*sections)) ||
        sections->count == 0 || sections->count > 128 || !sections->stuff ||
        !readable(sections->stuff, (size_t)sections->count * sizeof(void *))) {
        logline("[stobe] EQUIP_ITEM invalid inventory section list inv=%p", inv);
        return 0;
    }

    void *source = NULL, *destination = NULL, *occupied = NULL;
    char source_name[96] = {0}, destination_name[96] = {0}, occupied_name[96] = {0};
    for (uint32_t i = 0; i < sections->count; ++i) {
        void *section = sections->stuff[i];
        if (!section || !readable(section, 0xD1)) continue;
        if (!source && g_stobe_invsect_hasitem(section, item)) {
            source = section;
            stobe_copy_native_string((void *)((uintptr_t)section + 0x08),
                                     source_name, sizeof(source_name));
            continue;
        }
        if (!*(unsigned char *)((uintptr_t)section + 0xB4) ||      /* isAnEquippedItemSection */
            !*(unsigned char *)((uintptr_t)section + 0xD0) ||      /* enabled */
            *(int *)((uintptr_t)section + 0xB8) != slot)           /* limitedSlot */
            continue;
        if (g_stobe_invsect_getitem(section)) {
            if (!occupied) {
                occupied = section;
                stobe_copy_native_string((void *)((uintptr_t)section + 0x08),
                                         occupied_name, sizeof(occupied_name));
            }
            continue;
        }
        if (!destination && g_stobe_invsect_hasroom(section, gd, qty)) {
            destination = section;
            stobe_copy_native_string((void *)((uintptr_t)section + 0x08),
                                     destination_name, sizeof(destination_name));
        }
    }

    if (!source) {
        logline("[stobe] EQUIP_ITEM source section not found item=%p", item);
        return 0;
    }
    if (*(unsigned char *)((uintptr_t)source + 0xB4)) {
        logline("[stobe] EQUIP_ITEM source is already an equipment section item=%p section=%s",
                item, source_name[0] ? source_name : "(unknown)");
        return 0;
    }
    if (!destination) {
        /* No auto-swap: replacing worn gear is a separate decision. */
        logline("[stobe] EQUIP_ITEM no free equipment section slot=%d item=%p occupied=%s",
                slot, item, occupied ? (occupied_name[0] ? occupied_name : "(unnamed)") : "(none)");
        return 0;
    }

    logline("[stobe] EQUIP_ITEM section move begin item=%p qty=%d slot=%d source=%s dest=%s",
            item, qty, slot,
            source_name[0] ? source_name : "(unknown)",
            destination_name[0] ? destination_name : "(unknown)");

    if (!g_stobe_invsect_removeitem(source, item)) {
        logline("[stobe] EQUIP_ITEM source section remove failed item=%p source=%s",
                item, source_name[0] ? source_name : "(unknown)");
        return 0;
    }
    if (!g_stobe_invsect_additem(destination, item, qty)) {
        int restored = g_stobe_invsect_additem(source, item, qty);
        logline("[stobe] EQUIP_ITEM destination add failed item=%p dest=%s rollback=%s",
                item, destination_name[0] ? destination_name : "(unknown)",
                restored ? "ok" : "FAILED");
        return 0;
    }

    if (!readable(item, ITEM_IS_EQUIPPED + 1))
        return 0;
    int equipped = *(unsigned char *)((uintptr_t)item + ITEM_IS_EQUIPPED) != 0;
    int source_still_has = g_stobe_invsect_hasitem(source, item);
    int destination_has = g_stobe_invsect_hasitem(destination, item);
    logline("[stobe] EQUIP_ITEM section move result item=%p qty=%d source=%s dest=%s sourceHas=%d destHas=%d equippedAfter=%d",
            item, qty,
            source_name[0] ? source_name : "(unknown)",
            destination_name[0] ? destination_name : "(unknown)",
            source_still_has, destination_has, equipped);

    if (!equipped || source_still_has || !destination_has) {
        if (destination_has)
            (void)g_stobe_invsect_removeitem(destination, item);
        int restored = g_stobe_invsect_additem(source, item, qty);
        logline("[stobe] EQUIP_ITEM verification failed; rollback=%s item=%p",
                restored ? "ok" : "FAILED", item);
        return 0;
    }

    if (g_stobe_rethink)
        g_stobe_rethink(npc);
    return 1;
}

static void stobe_unequip_request_tick(void *gw)
{
    static DWORD last_check;
    DWORD now = GetTickCount();
    if (now - last_check < 50) return;
    last_check = now;

    char path[MAX_PATH * 2] = {0};
    if (!stobe_mod_path(path, sizeof(path), "unequip_item.request"))
        return;
    if (GetFileAttributesA(path) == INVALID_FILE_ATTRIBUTES)
        return;

    HANDLE h = CreateFileA(path, GENERIC_READ,
                           FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
                           NULL, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);
    if (h == INVALID_HANDLE_VALUE) return;
    char buf[384] = {0};
    DWORD got = 0;
    BOOL ok = ReadFile(h, buf, sizeof(buf) - 1, &got, NULL);
    CloseHandle(h);
    if (!ok || !got) {
        DeleteFileA(path);
        return;
    }
    buf[got] = '\0';
    DeleteFileA(path);

    char *tab = strchr(buf, '\t');
    if (!tab) {
        logline("[stobe] unequip request invalid payload");
        return;
    }
    *tab++ = '\0';
    char *eol = strpbrk(tab, "\r\n");
    if (eol) *eol = '\0';
    unsigned long serial_ul = strtoul(buf, NULL, 10);
    uint32_t serial = (uint32_t)serial_ul;
    if (!serial || !*tab) {
        logline("[stobe] unequip request missing serial/item");
        return;
    }

    __try {
    void *npc = stobe_find_character_by_serial(gw, serial);
    if (!npc) {
        g_guard_armed = 0;
        logline("[stobe] unequip target not found serial=%u item=%s", serial, tab);
        return;
    }
    char matched[160] = {0};
    void *item = stobe_find_equipped_item(npc, tab, matched, sizeof(matched));
    if (!item) {
        g_guard_armed = 0;
        logline("[stobe] unequip no equipped match serial=%u query=%s", serial, tab);
        return;
    }
    int success = stobe_unequip_item(npc, item);
    g_guard_armed = 0;
    logline("[stobe] UNEQUIP_ITEM serial=%u query=%s matched=%s result=%s",
            serial, tab, matched[0] ? matched : "(unknown)", success ? "ok" : "failed");
    } __except (STOBE_SEH_FILTER) {
        logline("[stobe] unequip request faulted safely serial=%u item=%s code=0x%08lx", serial, tab, g_seh_code);
    }
}


