static int stobe_resolve_action_exports(void)
{
    HMODULE klib = GetModuleHandleA("KenshiLib.dll");
    if (!klib) return 0;
    if (!g_stobe_getobjects)
        g_stobe_getobjects = (stobe_getobjects_t)GetProcAddress(klib, KLIB_GETOBJECTS_SYM);
    if (!g_stobe_getinv)
        g_stobe_getinv = (stobe_getinv_t)GetProcAddress(klib, KLIB_GETINV_SYM);
    if (!g_stobe_equip)
        g_stobe_equip = (stobe_equip_t)GetProcAddress(klib, KLIB_EQUIP_SYM);
    if (!g_stobe_drop)
        g_stobe_drop = (stobe_drop_t)GetProcAddress(klib, KLIB_DROP_SYM);
    if (!g_stobe_primary_weapon)
        g_stobe_primary_weapon = (stobe_getweapon_t)GetProcAddress(klib, KLIB_PRIMARY_WEAPON_SYM);
    if (!g_stobe_secondary_weapon)
        g_stobe_secondary_weapon = (stobe_getweapon_t)GetProcAddress(klib, KLIB_SECONDARY_WEAPON_SYM);
    if (!g_stobe_getorders)
        g_stobe_getorders = (stobe_getorders_t)GetProcAddress(klib, KLIB_GETORDERS_SYM);
    if (!g_stobe_addorder)
        g_stobe_addorder = (stobe_addorder_t)GetProcAddress(klib, KLIB_ADDORDER_SYM);
    if (!g_stobe_sheathe)
        g_stobe_sheathe = (stobe_sheathe_t)GetProcAddress(klib, KLIB_SHEATHE_SYM);
    if (!g_stobe_lookat)
        g_stobe_lookat = (stobe_lookat_t)GetProcAddress(klib, KLIB_LOOKAT_SYM);
    if (!g_stobe_rethink)
        g_stobe_rethink = (stobe_rethink_t)GetProcAddress(klib, KLIB_RETHINK_SYM);
    return g_stobe_getinv && g_stobe_equip && g_stobe_getorders &&
           g_stobe_addorder && g_stobe_sheathe && g_stobe_lookat &&
           g_stobe_rethink;
}

static void *stobe_find_inventory_item(void *npc, const char *query,
                                       char *matched_name, size_t matched_sz)
{
    if (matched_name && matched_sz) matched_name[0] = '\0';
    if (!npc || !query || !*query || !stobe_resolve_action_exports())
        return NULL;
    void *inv = g_stobe_getinv(npc);
    if (!inv || !readable((void *)((uintptr_t)inv + INV_ALLITEMS), sizeof(StobePtrLektor)))
        return NULL;
    StobePtrLektor *items = (StobePtrLektor *)((uintptr_t)inv + INV_ALLITEMS);
    if (!items->stuff || items->count > 2048 ||
        !readable(items->stuff, items->count * sizeof(void *)))
        return NULL;

    char q[192] = {0};
    strncpy(q, query, sizeof(q) - 1);
    stobe_ascii_lower(q);

    void *partial = NULL;
    int partial_ambiguous = 0;
    char partial_name[160] = {0};
    for (uint32_t i = 0; i < items->count; ++i) {
        void *item = items->stuff[i];
        if (!readable(item, ITEM_IS_EQUIPPED + 1)) continue;
        char name[160] = {0};
        if (!stobe_real_item_gamedata(item, name, sizeof(name), NULL))
            continue;
        char lower[160] = {0};
        strncpy(lower, name, sizeof(lower) - 1);
        stobe_ascii_lower(lower);
        if (strcmp(lower, q) == 0) {
            if (matched_name && matched_sz) {
                strncpy(matched_name, name, matched_sz - 1);
                matched_name[matched_sz - 1] = '\0';
            }
            return item;
        }
        if (strstr(lower, q) || strstr(q, lower)) {
            if (partial && partial != item) {
                partial_ambiguous = 1;
                continue;
            }
            if (!partial_ambiguous) {
                partial = item;
                strncpy(partial_name, name, sizeof(partial_name) - 1);
            }
        }
    }
    if (partial_ambiguous) return NULL;
    if (partial && matched_name && matched_sz) {
        strncpy(matched_name, partial_name, matched_sz - 1);
        matched_name[matched_sz - 1] = '\0';
    }
    return partial;
}

static void stg_cancel_standing_goals(uint32_t actor_serial); /* stobe_task_goals.inc */

static int stobe_issue_order(void *actor, int task_type, void *subject)
{
    if (!actor || !stobe_resolve_action_exports()) return 0;
    void *orders = g_stobe_getorders(actor);
    if (!orders || !readable(orders, 8)) return 0;
    Vec3 location = {0,0,0};
    if (subject) {
        if (!char_position(subject, &location) &&
            readable((void *)((uintptr_t)subject + 0x48), sizeof(Vec3)))
            location = *(Vec3 *)((uintptr_t)subject + 0x48);
    } else if (!char_position(actor, &location)) {
        return 0;
    }
    const void *subject_hand = (void *)((uintptr_t)(subject ? subject : actor) + CHAR_HANDLE);
    if (!readable(subject_hand, 0x20)) return 0;
    g_stobe_addorder(orders, task_type, subject_hand, &location, 0, 0);
    g_stobe_rethink(actor);
    return 1;
}

static void *stobe_find_building_by_query(void *gw, void *actor, const char *query,
                                          char *matched_name, size_t matched_sz)
{
    if (matched_name && matched_sz) matched_name[0] = '\0';
    if (!gw || !actor || !stobe_resolve_action_exports() || !g_stobe_getobjects)
        return NULL;
    Vec3 center = {0,0,0};
    if (!char_position(actor, &center)) return NULL;

    static void *nearby[1024]; /* item 89: spare room so the game never grows our buffer */
    memset(nearby, 0, sizeof(nearby));
    StobePtrLektor out;
    memset(&out, 0, sizeof(out));
    out.max_size = 1024;
    out.stuff = nearby;
    g_stobe_getobjects(gw, &out, &center, 450.0f, 0, 192, actor);
    if (out.stuff != nearby || out.count > 1024) return NULL;

    char q[192] = {0};
    strncpy(q, query ? query : "", sizeof(q) - 1);
    stobe_ascii_lower(q);
    int generic = !q[0] || !strcmp(q, "this") || !strcmp(q, "that") ||
                  !strcmp(q, "building") || !strcmp(q, "object") ||
                  !strcmp(q, "nearby");

    void *best = NULL;
    float best_dist2 = 1.0e30f;
    int best_score = -1;
    char best_name[160] = {0};

    for (uint32_t i = 0; i < out.count; ++i) {
        void *building = out.stuff[i];
        if (!readable(building, 0x60)) continue;
        void *gd = *(void **)((uintptr_t)building + 0x40);
        char name[160] = {0};
        if (gd && readable(gd, GD_NAME + 0x20))
            stobe_copy_native_string((void *)((uintptr_t)gd + GD_NAME), name, sizeof(name));
        char lower[160] = {0};
        strncpy(lower, name, sizeof(lower) - 1);
        stobe_ascii_lower(lower);

        int score = generic ? 1 : 0;
        if (!generic && lower[0]) {
            if (!strcmp(lower, q)) score = 1000;
            else if (strstr(lower, q) || strstr(q, lower)) score = 500;
        }
        if (score <= 0) continue;

        Vec3 pos = *(Vec3 *)((uintptr_t)building + 0x48);
        float dx = pos.x - center.x, dy = pos.y - center.y, dz = pos.z - center.z;
        float dist2 = dx*dx + dy*dy + dz*dz;
        if (score > best_score || (score == best_score && dist2 < best_dist2)) {
            best = building;
            best_score = score;
            best_dist2 = dist2;
            strncpy(best_name, name[0] ? name : query, sizeof(best_name) - 1);
        }
    }
    if (best && matched_name && matched_sz) {
        strncpy(matched_name, best_name, matched_sz - 1);
        matched_name[matched_sz - 1] = '\0';
    }
    return best;
}

static int stobe_issue_building_order(void *actor, void *building, int task_type)
{
    if (!actor || !building || !stobe_resolve_action_exports()) return 0;
    void *orders = g_stobe_getorders(actor);
    if (!orders || !readable(orders, 8) || !readable(building, 0x78)) return 0;
    Vec3 location = *(Vec3 *)((uintptr_t)building + 0x48);
    const void *subject_hand = (void *)((uintptr_t)building + CHAR_HANDLE);
    if (!readable(subject_hand, 0x20)) return 0;
    g_stobe_addorder(orders, task_type, subject_hand, &location, 0, 0);
    g_stobe_rethink(actor);
    return 1;
}

#define KLIB_CLEAR_GOALS_SYM "?clearAllAIGoals@Character@@QEAAXXZ"
#define KLIB_END_COMBAT_SYM "?endCombatMode@Character@@QEAAXXZ"
#define KLIB_CLEAR_ORDERS_SYM "?clearOrders@OrdersReceiver@@QEAAXXZ"
typedef void (*stobe_object_void_t)(void *object);
static stobe_object_void_t g_stobe_clear_goals;
static stobe_object_void_t g_stobe_end_combat;
static stobe_object_void_t g_stobe_clear_orders;

static int stobe_resolve_fight_exports(void)
{
    HMODULE klib = GetModuleHandleA("KenshiLib.dll");
    if (!klib || !stobe_resolve_action_exports()) return 0;
    if (!g_stobe_clear_goals)
        g_stobe_clear_goals = (stobe_object_void_t)GetProcAddress(klib, KLIB_CLEAR_GOALS_SYM);
    if (!g_stobe_end_combat)
        g_stobe_end_combat = (stobe_object_void_t)GetProcAddress(klib, KLIB_END_COMBAT_SYM);
    if (!g_stobe_clear_orders)
        g_stobe_clear_orders = (stobe_object_void_t)GetProcAddress(klib, KLIB_CLEAR_ORDERS_SYM);
    return g_stobe_clear_goals && g_stobe_end_combat && g_stobe_clear_orders;
}

/* Individual disengage. STOBE's STOP_ATTACK is a faction ceasefire and refuses
 * personal brawls (reason=faction_not_supported), so this stops one NPC's
 * fight: drop its AI goals and orders, leave combat mode, sheathe, re-think. */
static void stobe_disengage_character(void *npc)
{
    g_stobe_clear_goals(npc);
    void *orders = g_stobe_getorders(npc);
    if (orders && readable(orders, 8))
        g_stobe_clear_orders(orders);
    g_stobe_end_combat(npc);
    g_stobe_sheathe(npc);
    g_stobe_rethink(npc);
}

#define STOBE_FIGHT_TRUCE_SLOTS 8
static struct {
    uint32_t serial;
    DWORD started;
    int passes;
} g_stobe_fight_truce[STOBE_FIGHT_TRUCE_SLOTS];

static void stobe_fight_truce_add(uint32_t serial)
{
    int slot = -1;
    for (int i = 0; i < STOBE_FIGHT_TRUCE_SLOTS; ++i) {
        if (g_stobe_fight_truce[i].serial == serial) { slot = i; break; }
        if (slot < 0 && !g_stobe_fight_truce[i].serial) slot = i;
    }
    if (slot < 0) slot = 0;
    g_stobe_fight_truce[slot].serial = serial;
    g_stobe_fight_truce[slot].started = GetTickCount();
    g_stobe_fight_truce[slot].passes = 0;
}

/* Vanilla AI can re-acquire the old target a moment later. Re-apply the
 * disengage at ~3 s, ~8 s and ~15 s, then let the NPC's AI run normally. */
static void stobe_fight_truce_tick(void *gw)
{
    static const DWORD marks[3] = {3000, 8000, 15000};
    DWORD now = GetTickCount();
    for (volatile int i = 0; i < STOBE_FIGHT_TRUCE_SLOTS; ++i) {
        uint32_t serial = g_stobe_fight_truce[i].serial;
        if (!serial) continue;
        int pass = g_stobe_fight_truce[i].passes;
        if (pass >= 3) { g_stobe_fight_truce[i].serial = 0; continue; }
        if (now - g_stobe_fight_truce[i].started < marks[pass]) continue;
        g_stobe_fight_truce[i].passes = pass + 1;
        void *npc = NULL;
        __try {
            npc = stobe_find_character_by_serial(gw, serial);
            if (npc && stobe_resolve_fight_exports())
                stobe_disengage_character(npc);
        } __except (STOBE_SEH_FILTER) {
            g_stobe_fight_truce[i].serial = 0;
            logline("[stobe] STOP_FIGHT reapply faulted safely serial=%u code=0x%08lx", serial, g_seh_code);
            continue;
        }
        logline("[stobe] STOP_FIGHT reapply serial=%u pass=%d found=%d", serial, pass + 1, npc ? 1 : 0);
    }
}

#define STOBE_TASK_FOLLOW_PLAYER_ORDER 44

/* 1 when c is one of the player's own characters (squad list). */
static int stobe_is_player_squad_char(void *gw, void *c)
{
    if (!c || !readable(gw, GW_PLAYER + 8)) return 0;
    void *player = *(void **)((uintptr_t)gw + GW_PLAYER);
    if (!readable(player, PI_PLAYERCHARS + LEK_STUFF + 8)) return 0;
    uint32_t count = *(uint32_t *)((uintptr_t)player + PI_PLAYERCHARS + LEK_COUNT);
    void **stuff = *(void ***)((uintptr_t)player + PI_PLAYERCHARS + LEK_STUFF);
    if (!stuff || count > 4096 || !readable(stuff, count * sizeof(void *))) return 0;
    for (uint32_t i = 0; i < count; i++) if (stuff[i] == c) return 1;
    return 0;
}

static int stobe_handle_general_action(void *gw, uint32_t actor_serial,
                                       const char *command, uint32_t target_serial,
                                       const char *argument)
{
    void *actor = stobe_find_character_by_serial(gw, actor_serial);
    if (!actor) {
        logline("[stobe] ACTION_BRIDGE actor not found serial=%u command=%s",
                actor_serial, command ? command : "");
        return 0;
    }
    void *target = target_serial ? stobe_find_character_by_serial(gw, target_serial) : NULL;
    const char *arg = argument ? argument : "";

    if (!strcmp(command, "EQUIP_ITEM")) {
        char matched[160] = {0};
        void *item = stobe_find_inventory_item(actor, arg, matched, sizeof(matched));
        if (!item) {
            logline("[stobe] ACTION_BRIDGE EQUIP_ITEM actor=%u query=%s no inventory match (missing or ambiguous)",
                    actor_serial, arg);
            return 0;
        }
        if (*(unsigned char *)((uintptr_t)item + ITEM_IS_EQUIPPED)) return 1;
        int ok = stobe_equip_item(actor, item);
        logline("[stobe] ACTION_BRIDGE EQUIP_ITEM actor=%u query=%s matched=%s result=%s",
                actor_serial, arg, matched, ok ? "ok" : "failed");
        return ok;
    }

    if (!strcmp(command, "STOP_FIGHT")) {
        if (!stobe_resolve_fight_exports()) {
            logline("[stobe] STOP_FIGHT exports missing");
            return 0;
        }
        stobe_disengage_character(actor);
        stobe_fight_truce_add(actor_serial);
        return 1;
    }

    if (!strcmp(command, "SHEATHE_WEAPON")) {
        g_stobe_sheathe(actor);
        g_stobe_rethink(actor);
        return 1;
    }

    if (!strcmp(command, "DRAW_WEAPON")) {
        return stobe_issue_order(actor, STOBE_TASK_EQUIP_WEAPON, NULL);
    }

    if (!strcmp(command, "FACE_TARGET")) {
        if (!target) return 0;
        Vec3 pos = {0,0,0};
        if (!char_position(target, &pos)) return 0;
        g_stobe_lookat(actor, &pos, 1);
        return 1;
    }

    if (!strcmp(command, "DROP_WEAPON") || !strcmp(command, "SURRENDER") ||
        !strcmp(command, "DISARM_SELF")) {
        g_stobe_sheathe(actor);
        void *inv = g_stobe_getinv(actor);
        if (!inv) return 0;
        void *item = g_stobe_primary_weapon ? g_stobe_primary_weapon(inv) : NULL;
        if (!item && g_stobe_secondary_weapon)
            item = g_stobe_secondary_weapon(inv);
        if (!item || !readable(item, ITEM_IS_EQUIPPED + 1)) {
            g_stobe_rethink(actor);
            return !strcmp(command, "SURRENDER");
        }
        if (!strcmp(command, "DROP_WEAPON")) {
            if (!g_stobe_drop) return 0;
            g_stobe_drop(inv, item);
        } else {
            if (!stobe_unequip_item(actor, item)) return 0;
        }
        g_stobe_rethink(actor);
        return 1;
    }

    int task = -1;
    if (!strcmp(command, "FIRST_AID")) task = STOBE_TASK_FIRST_AID;
    else if (!strcmp(command, "BODYGUARD") || !strcmp(command, "GUARD_TARGET"))
        task = STOBE_TASK_BODYGUARD;
    else if (!strcmp(command, "PATROL")) task = STOBE_TASK_PATROL;
    else if (!strcmp(command, "HOLD_POSITION")) task = STOBE_TASK_HOLD_POSITION;
    else if (!strcmp(command, "MOVE_TO_TARGET")) task = STOBE_TASK_GET_NEAR_TO;
    else if (!strcmp(command, "RESCUE")) task = STOBE_TASK_FIND_RESCUE;
    else if (!strcmp(command, "PUT_IN_BED")) task = STOBE_TASK_FIND_BED_PUT_IN;
    else if (!strcmp(command, "LOOT_TARGET")) task = STOBE_TASK_LOOT_TARGET;
    else if (!strcmp(command, "IMPRISON")) task = STOBE_TASK_FIND_CAGE_PUT_IN;
    else if (!strcmp(command, "RELEASE_PRISONER")) task = STOBE_TASK_RELEASE_PRISONER;

    if (task == STOBE_TASK_PATROL || task == STOBE_TASK_HOLD_POSITION ||
        task == STOBE_TASK_GET_NEAR_TO || task == STOBE_TASK_BODYGUARD) {
        /* A new standing order replaces patrols/guard duty and old orders (bug 63). */
        stg_cancel_standing_goals(actor_serial);
        if (stobe_resolve_fight_exports()) {
            void *o = g_stobe_getorders(actor);
            if (o && readable(o, 8)) g_stobe_clear_orders(o);
        }
    }
    if (task == STOBE_TASK_BODYGUARD && target &&
        stobe_is_player_squad_char(gw, actor) && stobe_is_player_squad_char(gw, target)) {
        /* Bug 86: BODYGUARD on one of the player's own characters is ignored by a
         * squad member's AI (she stood "aimless"); the player's own follow order is
         * FOLLOW_PLAYER_ORDER, which keeps her close and fighting for him. */
        task = STOBE_TASK_FOLLOW_PLAYER_ORDER;
        logline("[stobe] ACTION_BRIDGE %s squad->squad: using FOLLOW_PLAYER_ORDER", command);
    }
    if (task >= 0) {
        if ((task == STOBE_TASK_PATROL || task == STOBE_TASK_HOLD_POSITION) && !target)
            return stobe_issue_order(actor, task, NULL);
        if (!target) return 0;
        return stobe_issue_order(actor, task, target);
    }

    if (!strcmp(command, "REPAIR") || !strcmp(command, "BUILD")) {
        char matched[160] = {0};
        void *building = stobe_find_building_by_query(gw, actor, arg, matched, sizeof(matched));
        if (!building) {
            logline("[stobe] ACTION_BRIDGE %s no building match actor=%u query=%s",
                    command, actor_serial, arg);
            return 0;
        }
        int ok = stobe_issue_building_order(
            actor, building, !strcmp(command, "REPAIR") ? STOBE_TASK_REPAIR : STOBE_TASK_BUILD);
        logline("[stobe] ACTION_BRIDGE %s actor=%u query=%s matched=%s result=%s",
                command, actor_serial, arg, matched, ok ? "ok" : "failed");
        return ok;
    }

    return 0;
}

static void stobe_general_action_request_tick(void *gw)
{
    static DWORD last_check;
    DWORD now = GetTickCount();
    if (now - last_check < 50) return;
    last_check = now;

    char path[MAX_PATH * 2] = {0};
    if (!stobe_mod_path(path, sizeof(path), "stobe_action.request")) return;
    if (GetFileAttributesA(path) == INVALID_FILE_ATTRIBUTES) return;

    HANDLE h = CreateFileA(path, GENERIC_READ,
                           FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
                           NULL, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);
    if (h == INVALID_HANDLE_VALUE) return;
    char buf[640] = {0};
    DWORD got = 0;
    BOOL ok = ReadFile(h, buf, sizeof(buf) - 1, &got, NULL);
    CloseHandle(h);
    DeleteFileA(path);
    if (!ok || !got) return;
    buf[got] = '\0';

    char *fields[4] = {0};
    int field_count = 0;
    char *cursor = buf;
    while (field_count < 4) {
        fields[field_count++] = cursor;
        char *tab = strchr(cursor, '\t');
        if (!tab) break;
        *tab = '\0';
        cursor = tab + 1;
    }
    if (field_count < 2) {
        logline("[stobe] ACTION_BRIDGE invalid payload");
        return;
    }
    char *eol = strpbrk(fields[field_count - 1], "\r\n");
    if (eol) *eol = '\0';

    uint32_t actor_serial = (uint32_t)strtoul(fields[0], NULL, 10);
    char command[80] = {0};
    strncpy(command, fields[1], sizeof(command) - 1);
    for (char *p = command; *p; ++p)
        if (*p >= 'a' && *p <= 'z') *p = (char)(*p - 'a' + 'A');
    uint32_t target_serial = field_count >= 3
        ? (uint32_t)strtoul(fields[2], NULL, 10) : 0;
    const char *argument = field_count >= 4 ? fields[3] : "";

    if (!actor_serial || !command[0]) {
        logline("[stobe] ACTION_BRIDGE missing actor/command");
        return;
    }

    int success = 0;
    __try {
        success = stobe_handle_general_action(
            gw, actor_serial, command, target_serial, argument);
    } __except (STOBE_SEH_FILTER) {
        logline("[stobe] ACTION_BRIDGE faulted safely actor=%u command=%s code=0x%08lx",
                actor_serial, command, g_seh_code);
        return;
    }
    logline("[stobe] ACTION_BRIDGE command=%s actor=%u target=%u arg=%s result=%s",
            command, actor_serial, target_serial, argument,
            success ? "ok" : "failed");
}

/* ==== stobe_work_planner.inc ==== */
/* STOBE persistent work-goal planner. Included by kenshifp_client.c.
 * Natural-language dialogue creates finite output goals; this module uses
 * Kenshi's real production/crafting/job APIs and recursively resolves missing
 * inputs. No LLM calls occur in this executor. */
#define WGP_MAX_GOALS 16
#define WGP_MAX_SUBSTATE 24
#define WGP_MAX_DEPTH 10
#define WGP_MAX_PLAN_NODES 64
#define WGP_MAX_BUILDINGS 256
#define WGP_MAX_CRAFTS 128
#define WGP_MAX_MISSING 32
#define WGP_TICK_MS 1000
/* Game-time budgets (bug 80): these were real-time values tuned while testing
 * at 10x; on the goal clock (bug 78) they must be 10x larger in game ms. */
#define WGP_STALL_MS 1800000
#define WGP_REORDER_MS 30000 /* bug 106: re-send the operate order only after 30 game s idle */
#define WGP_UNIT_MAX_MS 14400000 /* bug 93: most game time one unit may take while she stands at the machine */
#define WGP_OPERATE_NEAR 120.0f
#define WGP_DEP_STALL_MS 9000000
#define WGP_POWER_WAIT_MS 300000
#define WGP_TRAVEL_STALL_MS 2400000
#define WGP_ARRIVE_DIST 65.0f
#define WGP_SCAN_RADIUS 1400.0f

#define WGP_BF_MINE 1
#define WGP_BF_CRAFTING 10 /* item 93b: BF_CRAFTING (9 is BF_SHOP) */
#define WGP_BF_MINE_NATURAL 27 /* item 93b: BF_MINE_NATURAL (25 is BF_SKELETON_BED) */
#define WGP_TASK_COLLECT_OUTPUT 92

#define WGP_GETPROD_SYM "?_NV_getProductionBuilding@Building@@QEAAPEAVProductionBuilding@@XZ"
#define WGP_GETINV_BUILDING_SYM "?_NV_getInventory@Building@@QEBAPEAVInventory@@XZ"
#define WGP_ISPLAYER_BUILDING_SYM "?isThePlayer@Building@@QEBA_NXZ"
#define WGP_SPECIAL_SYM "?_NV_getSpecialFunction@Building@@QEBA?AW4BuildingFunction@@XZ"
#define WGP_AVAILABLE_CRAFTS_SYM "?getAvailableCrafts@CraftingBuilding@@QEAAXAEAV?$lektor@VGameDataGroup@@@@@Z"
#define WGP_ADD_CRAFT_SYM "?_addCraft@CraftingBuilding@@QEAAPEAVCraftingItem@@PEAVGameData@@0MVYesNoMaybe@@@Z"

typedef void *(*wgp_getprod_t)(void *);
typedef void *(*wgp_getinv_building_t)(void *);
typedef unsigned char (*wgp_isplayer_building_t)(void *);
